Query: (() => {
    const db = { items: ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i'] };
    return {
      paginated: (_, { page, pageSize }) => {
        const all = db.items;
        const start = (page - 1) * pageSize;
        return {
          items: all.slice(start, start + pageSize),
          totalPages: Math.ceil(all.length / pageSize)
        };
      }
    };
  })()

