payload.resolver_code:
Query: (() => {
    const db = { packages: [{ pkg: 'lodash', version: '4.17.20', downloads: 80000 }, { pkg: 'lodash', version: '4.17.21', downloads: 120000 }] };
    return {
      latestVersion: (_, { pkg }) => {
        const versions = db.packages.filter(p => p.pkg === pkg);
        if (!versions.length) return null;
        return versions.reduce((best, cur) => cur.downloads > best.downloads ? cur : best);
      }
    };
  })()

