Query: {
  posts: (_, { first, after }) => {
    const allPosts = [
      { id: '1', title: 'Alpha' },
      { id: '2', title: 'Beta' },
      { id: '3', title: 'Gamma' },
      { id: '4', title: 'Delta' }
    ];
    let startIndex = 0;
    if (after) {
      const idx = allPosts.findIndex(p => p.id === after);
      startIndex = idx + 1;
    }
    const slice = allPosts.slice(startIndex, startIndex + first);
    const edges = slice.map(p => ({ cursor: p.id, node: p }));
    const hasNextPage = startIndex + first < allPosts.length;
    const endCursor = edges.length ? edges[edges.length - 1].cursor : null;
    return { edges, pageInfo: { hasNextPage, endCursor } };
  }
}

