  comments(postId: "post1", first: 2, after: "c1") {
    edges { cursor node { text } }
    pageInfo { hasNextPage endCursor }
  }
}

payload.resolver_code:
Query: {
  comments: (_, { postId, first, after }) => {
    const allComments = [
      { id: "c1", postId: "post1", text: "First!" },
      { id: "c2", postId: "post1", text: "Nice article" },
      { id: "c3", postId: "post1", text: "Learned a lot" },
      { id: "c4", postId: "post1", text: "Thanks for this" }
    ];
    const filtered = allComments.filter(c => c.postId === postId);
    const startIndex = after ? filtered.findIndex(c => c.id === after) + 1 : 0;
    const page = filtered.slice(startIndex, startIndex + first);
    const edges = page.map(c => ({ cursor: c.id, node: c }));
    const hasNextPage = startIndex + first < filtered.length;
    const endCursor = edges.length > 0 ? edges[edges.length - 1].cursor : null;
    return { edges, pageInfo: { hasNextPage, endCursor } };
  }
}

payload.schema_definition:
type Comment {
  id: ID!
  text: String!
}

type CommentEdge {
  cursor: String!
  node: Comment!
}

type PageInfo {
  hasNextPage: Boolean!
  endCursor: String
}

type CommentConnection {
  edges: [CommentEdge!]!
  pageInfo: PageInfo!
}

type Query {
  comments(postId: ID!, first: Int!, after: String): CommentConnection!
}

