Mutation: {
  updateTaskStatus: (_, { taskId, newStatus }) => {
    const tasks = [
      { id: "t1", title: "Write docs", status: "TODO" },
      { id: "t2", title: "Fix bug", status: "DONE" }
    ];
    const task = tasks.find(t => t.id === taskId);
    if (!task) {
      throw new Error("Task not found");
    }
    const allowedTransitions = { TODO: ["IN_PROGRESS"], IN_PROGRESS: ["DONE", "TODO"], DONE: [] };
    if (!allowedTransitions[task.status].includes(newStatus)) {
      throw new Error(`Cannot transition task from ${task.status} to ${newStatus}`);
    }
    task.status = newStatus;
    return task;
  }
},
Query: {
  task: (_, { id }) => {
    const tasks = [
      { id: "t1", title: "Write docs", status: "TODO" },
      { id: "t2", title: "Fix bug", status: "DONE" }
    ];
    return tasks.find(t => t.id === id) || null;
  }
}

