Mutation: {
  transferFunds: (_, { fromId, toId, amount }) => {
    const accounts = [ { id: "acc1", owner: "Dana", balance: 150.0 }, { id: "acc2", owner: "Marco", balance: 40.0 } ];
    const from = accounts.find(a => a.id === fromId);
    const to = accounts.find(a => a.id === toId);
    if (!from || !to) {
      throw new Error("Account not found");
    }
    if (from.balance < amount) {
      throw new Error("Insufficient funds");
    }
    from.balance -= amount;
    to.balance += amount;
    return { from, to };
  }
},
Query: {
  account: (_, { id }) => {
    const accounts = [ { id: "acc1", owner: "Dana", balance: 150.0 }, { id: "acc2", owner: "Marco", balance: 40.0 } ];
