  }
},
Account: {
  transactions: (account) => {
    const transactions = [
      { id: "tx1", accountId: "acc1", amount: -20.0, type: "DEBIT" },
      { id: "tx2", accountId: "acc1", amount: 100.0, type: "CREDIT" },
      { id: "tx3", accountId: "acc2", amount: -10.0, type: "DEBIT" }
    ];
