Column: { cards: (column, { last, before }) => {
  const store = {
    'eng/Doing': [['c1', 'Split resolver bundle', 3], ['c2', 'Cache warm path', 5]],
    'eng/Done': [['c3', 'Drop legacy loader', 2], ['c4', 'Add tracing spans', 8], ['c5', 'Pin graphql version', 1], ['c6', 'Backfill cursors', 13]]
  };
  const rows = (store[column.boardKey + '/' + column.name] || []).map((r) => ({ cursor: 'cur:' + r[0], node: { id: r[0], title: r[1], points: r[2] } }));
  let window = rows;
  if (before) { const idx = rows.findIndex((e) => e.cursor === before); if (idx !== -1) window = rows.slice(0, idx); }
  const trimmedFromStart = last != null && window.length > last;
  if (trimmedFromStart) window = window.slice(window.length - last);
  return { totalCount: rows.length, edges: window, hasNextPage: window.length > 0 && window[window.length - 1].cursor !== rows[rows.length - 1].cursor, hasPreviousPage: trimmedFromStart || (window.length > 0 && window[0].cursor !== rows[0].cursor) };
} },
