  signup: (() => {
    const taken = new Set(['ada@example.com']);
    let seq = 100;
    return (_, { input }) => {
      const errors = [];
      if (taken.has(input.email)) errors.push({ field: 'email', reason: 'already registered' });
      if (input.age < 18) errors.push({ field: 'age', reason: 'must be at least 18' });
      if (errors.length > 0) {
        return { __typename: 'ValidationFailure', errorCount: errors.length, errors: errors };
      }
      taken.add(input.email);
      seq += 1;
      return { __typename: 'SignupSuccess', account: { id: String(seq), email: input.email } };
    };
  })()
},
