payload.resolver_code:
Query: {
  invoice: () => {
    const mkLine = (sku, qty, unitPrice) => ({
      sku: sku,
      qty: qty,
      unitPrice: unitPrice,
      amount: function () { return Number((this.qty * this.unitPrice).toFixed(2)); }
    });
    const lines = [mkLine('AA-1', 3, 4.25), mkLine('BB-2', 2, 10.1)];
    return {
      number: 'INV-2031',
      lines: lines,
      subtotal: function () { return Number(lines.reduce((s, l) => s + l.qty * l.unitPrice, 0).toFixed(2)); },
      total: function (args) {
        const gross = lines.reduce((s, l) => s + l.qty * l.unitPrice, 0) * (1 + args.taxRate);
        return args.rounded ? Math.round(gross) : Number(gross.toFixed(4));
      }
    };
  }
}

