    const table = { EMAIL: { limit: 5000, used: 4990 }, SMS: { limit: 500, used: 120 }, PUSH: { limit: 20000, used: 20000 }, WEBHOOK: { limit: 100, used: 3 } };
    return Object.assign({ channel: channel }, table[channel]);
  },
  channels: () => ['EMAIL', 'SMS', 'PUSH', 'WEBHOOK'],
  busiest: () => {
    const table = { EMAIL: { limit: 5000, used: 4990 }, SMS: { limit: 500, used: 120 }, PUSH: { limit: 20000, used: 20000 }, WEBHOOK: { limit: 100, used: 3 } };
