Query: {
  lookup: (_parent, args) => {
    const corpus = ["alpha", "bravo", "charlie", "delta", "echo", "foxtrot"];
    const page = args.where.page;
    const hits = corpus.filter((w) => w.indexOf(args.where.term) >= 0);
