payload.resolver_code:
Query: {
  rows: (_parent, args) => {
    const data = [
      { id: "1", port: "SYD", cargo: "grain" },
      { id: "2", port: "MEL", cargo: "ore" },
      { id: "3", port: "SYD", cargo: "ore" },
      { id: "4", port: "BNE", cargo: "grain" }
    ];
    const test = (row, e) => {
      if (e.all) { return e.all.every((sub) => test(row, sub)); }
      if (e.any) { return e.any.some((sub) => test(row, sub)); }
      if (e.not) { return !test(row, e.not); }
      return row[e.field] === e.equals;
    };
    return data.filter((row) => test(row, args.where));
  },
  matched: (_parent, args) => {
    const data = [
      { id: "1", port: "SYD", cargo: "grain" },
      { id: "2", port: "MEL", cargo: "ore" },
      { id: "3", port: "SYD", cargo: "ore" },
      { id: "4", port: "BNE", cargo: "grain" }
    ];
    const test = (row, e) => {
      if (e.all) { return e.all.every((sub) => test(row, sub)); }
      if (e.any) { return e.any.some((sub) => test(row, sub)); }
      if (e.not) { return !test(row, e.not); }
      return row[e.field] === e.equals;
    };
    return data.filter((row) => test(row, args.where)).length;
  }
}

