},
Mutation: {
  moveItem: (_, { itemId, toBinId, quantity }) => {
    const bins = { bin1: { id: "bin1", capacity: 100, currentLoad: 90 } };
    const items = { it1: { id: "it1", name: "Pallet", quantity: 50 } };
    const bin = bins[toBinId];
