{
  bill: invoice(id: "INV-7") {
    id
    currency
    visible: lines { sku quantity unitCents status }
    all: lines(includeVoided: true) { sku status }
    subtotalCents
    discountCents
    payableCents
  }
}

payload.resolver_code:
Query: {
  invoice: (_, { id }) => {
    const invoices = [{
      id: "INV-7",
      currency: "USD",
      lines: [
        { sku: "A-RED", quantity: 2, unitCents: 1500, status: "ACTIVE" },
        { sku: "B-OLD", quantity: 1, unitCents: 2500, status: "VOIDED" },
        { sku: "C-BLU", quantity: 3, unitCents: 900, status: "ACTIVE" }
      ]
    }];
    return invoices.find(invoice => invoice.id === id) || null;
  }
},
Invoice: {
  lines: (invoice, { includeVoided }) =>
    includeVoided ? invoice.lines : invoice.lines.filter(line => line.status === "ACTIVE"),
  subtotalCents: (invoice, { includeVoided }) => {
    const lines = includeVoided ? invoice.lines : invoice.lines.filter(line => line.status === "ACTIVE");
    return lines.reduce((sum, line) => sum + line.quantity * line.unitCents, 0);
  },
  discountCents: invoice => {
    const subtotal = invoice.lines
      .filter(line => line.status === "ACTIVE")
      .reduce((sum, line) => sum + line.quantity * line.unitCents, 0);
    return subtotal >= 5000 ? Math.floor(subtotal * 0.10) : 0;
  },
  payableCents: invoice => {
    const subtotal = invoice.lines
      .filter(line => line.status === "ACTIVE")
      .reduce((sum, line) => sum + line.quantity * line.unitCents, 0);
    const discount = subtotal >= 5000 ? Math.floor(subtotal * 0.10) : 0;
    return subtotal - discount;
  }
}

payload.schema_definition:
enum LineStatus { ACTIVE VOIDED }
type Line { sku: String!, quantity: Int!, unitCents: Int!, status: LineStatus! }
type Invoice {
  id: ID!
  currency: String!
  lines(includeVoided: Boolean = false): [Line!]!
  subtotalCents(includeVoided: Boolean = false): Int!
  discountCents: Int!
  payableCents: Int!
}
type Query { invoice(id: ID!): Invoice }
